-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.unpublish_log_drops_browse_indexes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ids text[];
begin
  if new.kind <> 'deck' then
    return null;
  end if;
  ids := array(select jsonb_array_elements_text(coalesce(new.removed -> 'assessments', '[]'::jsonb)));
  delete from public.anki_browse_indexes i where i.assessment_id = any (ids);
  if to_regclass('draft.anki_browse_indexes') is not null then
    execute 'delete from draft.anki_browse_indexes i where i.assessment_id = any ($1)' using ids;
  end if;
  return null;
end;
$function$;

grant execute on function public.unpublish_log_drops_browse_indexes() to service_role;
